contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 seedAmount) public {
        require(seedAmount > 0);
        c.seedMarket(seedAmount); if (__ESBMC_reverted()) return;
        c.getFreeKilo(); if (__ESBMC_reverted()) return;
        assert(c.getMyKilo() == c.STARTING_KILOS());
    }
    receive() external payable {}
}

