pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 seedAmount) internal {
        vm.assume(seedAmount > 0);
        try c.seedMarket(seedAmount) {} catch { return; }
        try c.getFreeKilo() {} catch { return; }
        assertTrue(c.getMyKilo() == c.STARTING_KILOS());
    }

    function testFuzz_run(uint256 seedAmount) public {
        _run(seedAmount);
    }

    receive() external payable {}
}
